using sv_319808aad2cf418e80e5d4165b957f20.Models;

namespace sv_319808aad2cf418e80e5d4165b957f20.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_319808aad2cf418e80e5d4165b957f20.Models;

namespace sv_319808aad2cf418e80e5d4165b957f20.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", 30),
            new(2, "Risotto alla Milanese", "Creamy saffron-infused Arborio rice cooked slowly in broth.", 45),
            new(3, "Tiramisu", "Layered dessert with espresso-soaked ladyfingers and mascarpone cream.", 25),
            new(4, "Pasta Carbonara", "Spaghetti with guanciale, egg yolk, Pecorino Romano, and black pepper.", 20),
        },
        [2] = new List<Recipe>
        {
            new(5, "Pad Thai", "Stir-fried rice noodles with shrimp, tofu, peanuts, and tamarind sauce.", 35),
            new(6, "Green Curry", "Coconut milk curry with Thai basil, bamboo shoots, and chicken.", 40),
            new(7, "Tom Yum Soup", "Hot and sour soup with lemongrass, galangal, and prawns.", 25),
            new(8, "Mango Sticky Rice", "Sweet glutinous rice topped with fresh mango and coconut cream.", 50),
        },
        [3] = new List<Recipe>
        {
            new(9, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion.", 60),
            new(10, "Guacamole", "Fresh avocado dip with lime, jalapeño, tomato, and cilantro.", 10),
            new(11, "Chicken Enchiladas", "Corn tortillas filled with chicken and smothered in red chile sauce.", 45),
            new(12, "Churros", "Fried dough pastry dusted with cinnamon sugar, served with chocolate sauce.", 30),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_319808aad2cf418e80e5d4165b957f20.Models
@using sv_319808aad2cf418e80e5d4165b957f20.Services
@inject IRecipeService RecipeService
@inject NavigationManager Navigation
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<div class="mb-3">
    <a href="/recipes/1?sort=@Sort" class="btn btn-outline-primary me-2 @(CuisineId == 1 ? "active" : "")">Italian</a>
    <a href="/recipes/2?sort=@Sort" class="btn btn-outline-primary me-2 @(CuisineId == 2 ? "active" : "")">Thai</a>
    <a href="/recipes/3?sort=@Sort" class="btn btn-outline-primary me-2 @(CuisineId == 3 ? "active" : "")">Mexican</a>
</div>

<div class="mb-3">
    <label class="form-label fw-bold">Sort by:</label>
    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm btn-outline-secondary me-1 @(Sort == "newest" ? "active" : "")">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm btn-outline-secondary @(Sort == "popular" ? "active" : "")">Popular</a>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <div class="d-flex align-items-center my-4">
        <div class="spinner-border text-primary me-3" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-2" role="status">
            <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
            Refreshing…
        </div>
    }

    <div class="row">
        @foreach (var recipe in GetSortedRecipes())
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-body-secondary">
                        <small>Prep time: @recipe.PrepTimeMinutes min</small>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;
    private CancellationTokenSource _disposeCts = new();

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            // Sort-only change — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for the previous cuisine.
        await CancelPendingLoadAsync();

        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        var cts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        _loadCts = cts;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a stale completion after a newer request replaced this one.
            if (cts.Token.IsCancellationRequested)
                return;

            _recipes = results;
            _loadedCuisineId = CuisineId;
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Expected when the user switched cuisines or navigated away — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please check your connection and try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
            return new List<Recipe>();

        return Sort?.ToLowerInvariant() switch
        {
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes.OrderByDescending(r => r.Id).ToList(), // "newest" or default
        };
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

